mapper.select:
SELECT max(revision) FROM (
  SELECT max(h.reg_dttm) AS revision FROM TB_SY_CHG_HIST h
  WHERE h.trgt_tbl_nm='TB_FI_ITEM' AND h.trgt_key=#{month} AND h.chg_item_nm='UI-10 월 저장'
  UNION ALL SELECT max(COALESCE(i.mod_dttm,i.reg_dttm)) FROM TB_FI_ITEM i WHERE i.fin_ym=#{month}
  UNION ALL SELECT max(COALESCE(l.mod_dttm,l.reg_dttm)) FROM TB_FI_LOAN l WHERE to_char(l.loan_dt,'YYYYMM')=#{month}
  UNION ALL SELECT max(COALESCE(x.mod_dttm,x.reg_dttm)) FROM TB_FI_XFER x WHERE to_char(x.xfer_dt,'YYYYMM')=#{month}
  UNION ALL SELECT max(COALESCE(a.mod_dttm,a.reg_dttm)) FROM TB_CO_PREV_ADJ a WHERE a.aply_ym=#{month}
  UNION ALL SELECT max(COALESCE(m.mod_dttm,m.reg_dttm)) FROM TB_FI_CARD_MON m WHERE m.pay_ym=#{month}
  UNION ALL SELECT max(COALESCE(p.mod_dttm,p.reg_dttm)) FROM TB_FI_CARD_PAY p WHERE p.pay_ym=#{month}
) revisions

mapper.update:
UPDATE TB_FI_LOAN SET loan_dt=#{row.date},io_cd=#{row.direction},amt=#{row.amount},cntprt_nm=#{row.counterparty},rmrk=#{row.memo},mod_user_id=#{actor},mod_dttm=clock_timestamp()
WHERE loan_sn=CAST(#{row.loanId} AS numeric) AND to_char(loan_dt,'YYYYMM')=#{month}
  AND mod_dttm IS NOT DISTINCT FROM #{row.modifiedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE}

UPDATE TB_FI_XFER SET xfer_dt=#{row.date},xfer_cls_cd=#{row.classification},item_nm=#{row.description},rcvr_nm=#{row.payee},amt=#{row.amount},rmrk=#{row.memo},mod_user_id=#{actor},mod_dttm=clock_timestamp()
WHERE xfer_sn=CAST(#{row.transferId} AS numeric) AND to_char(xfer_dt,'YYYYMM')=#{month}
  AND mod_dttm IS NOT DISTINCT FROM #{row.modifiedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE}

UPDATE TB_CO_PREV_ADJ SET trgt_ym=#{row.targetYearMonth},adj_item_cd=#{row.adjustmentItem},adj_amt=#{row.amount},adj_rsn=#{row.reason},mod_user_id=#{actor},mod_dttm=clock_timestamp()
WHERE adj_id=CAST(#{row.adjustmentId} AS numeric) AND aply_ym=#{month}
  AND mod_dttm IS NOT DISTINCT FROM #{row.modifiedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE}
